  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  padding: 1px 5px;
  border-radius: 3px;
  border: 1px solid currentColor;
  flex: 0 0 auto;
}

.badge-observed { color: var(--badge-observed); }
.badge-parsed { color: var(--badge-parsed); }
.badge-inferred { color: var(--badge-inferred); }

.copy-btn {
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 12px;
  line-height: 1;
  padding: 2px 4px;
  border-radius: 3px;
  flex: 0 0 auto;
}

.copy-btn:hover {
  background: var(--bg-subtle);
  color: var(--text);
}

.copy-btn.copied {
  color: var(--badge-observed);
}

.empty-state {
  color: var(--text-muted);
  padding: 24px 14px;
