5	function el<K extends keyof HTMLElementTagNameMap>(
6	  tag: K,
7	  className?: string,
8	  text?: string,
9	): HTMLElementTagNameMap[K] {
10	  const node = document.createElement(tag);
11	  if (className) node.className = className;
12	  if (text !== undefined) node.textContent = text;
